class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def distributeCandy(root):
    def helper(node):
        if not node:
            return 0
        left_balance = helper(node.left)
        right_balance = helper(node.right)
        moves[0] += abs(left_balance) + abs(right_balance)
        return node.val + left_balance + right_balance - 1

    moves = [0]
    helper(root)
    return moves[0]
